-- Flavor Flow full operations suite. Additive schema; no sends, charges or production seeds.
create table if not exists public.customer_consents(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,customer_id uuid not null references public.customer_profiles(id) on delete cascade,channel text not null check(channel in('whatsapp','email','sms')),status text not null check(status in('opted_in','opted_out')),source text not null,evidence jsonb not null default '{}',recorded_at timestamptz not null default now(),unique(customer_id,channel));
create table if not exists public.customer_segment_rules(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,kind text not null check(kind in('new','repeat','high_value','inactive','custom')),criteria jsonb not null,is_active boolean not null default true,created_at timestamptz default now());
create table if not exists public.retention_campaigns(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,segment_rule_id uuid references public.customer_segment_rules(id),name text not null,template text not null,scheduled_at timestamptz,status text not null default 'draft' check(status in('draft','scheduled','running','completed','cancelled')),created_at timestamptz default now());
create table if not exists public.message_deliveries(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.retention_campaigns(id) on delete cascade,customer_id uuid not null references public.customer_profiles(id),provider text,provider_message_id text,status text not null default 'queued' check(status in('queued','sent','delivered','failed','unsubscribed','suppressed')),error text,idempotency_key text not null unique,created_at timestamptz default now(),updated_at timestamptz default now());
alter table public.customer_profiles add column if not exists birth_date date; alter table public.customer_profiles add column if not exists preferences jsonb not null default '{}';
create table if not exists public.value_wallets(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),customer_id uuid references public.customer_profiles(id),kind text not null check(kind in('loyalty_points','promotional_credit','gift_card')),currency text,balance numeric(14,2) not null default 0,expires_at timestamptz,secret_hash text,public_code text,created_at timestamptz default now());
create table if not exists public.value_ledger(id uuid primary key default gen_random_uuid(),wallet_id uuid not null references public.value_wallets(id),amount numeric(14,2) not null,entry_type text not null check(entry_type in('earn','redeem','expire','reverse','refund','adjust')),order_id uuid references public.orders(id),reason text,idempotency_key text not null unique,created_at timestamptz default now());
create table if not exists public.product_costs(product_id uuid primary key references public.products(id) on delete cascade,ingredient_cost numeric(12,2) default 0,packaging_cost numeric(12,2) default 0,updated_at timestamptz default now());
create table if not exists public.order_costs(order_id uuid primary key references public.orders(id) on delete cascade,product_cost numeric(12,2) default 0,packaging_cost numeric(12,2) default 0,payment_fee numeric(12,2) default 0,delivery_cost numeric(12,2) default 0,commission numeric(12,2) default 0,discount numeric(12,2) default 0,refund numeric(12,2) default 0,inputs_complete boolean default false,calculated_at timestamptz default now());
create table if not exists public.substitution_proposals(id uuid primary key default gen_random_uuid(),order_item_id uuid not null references public.order_items(id),replacement_product_id uuid not null references public.products(id),access_token uuid not null default gen_random_uuid() unique,price_difference numeric(12,2) not null,status text not null default 'pending' check(status in('pending','accepted','rejected','cancel_requested','expired','unavailable')),expires_at timestamptz not null,version integer not null default 1,created_by uuid references auth.users(id),created_at timestamptz default now(),resolved_at timestamptz);
create table if not exists public.order_issues(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),order_item_id uuid references public.order_items(id),access_token uuid not null default gen_random_uuid() unique,issue_type text not null check(issue_type in('missing','incorrect','quality','late','other')),description text,status text not null default 'open' check(status in('open','reviewing','resolved','rejected')),assigned_to uuid references auth.users(id),created_at timestamptz default now(),resolved_at timestamptz);
create table if not exists public.resolution_actions(id uuid primary key default gen_random_uuid(),issue_id uuid not null references public.order_issues(id),action_type text not null check(action_type in('message','replacement','credit','partial_refund','full_refund','reject')),amount numeric(12,2),reason text not null,approved_by uuid references auth.users(id),idempotency_key text not null unique,created_at timestamptz default now());
create table if not exists public.limited_offers(id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id),product_id uuid not null references public.products(id),offer_price numeric(12,2) not null check(offer_price>=0),total_quantity integer not null check(total_quantity>0),reserved_quantity integer not null default 0,sold_quantity integer not null default 0,sale_starts_at timestamptz not null,sale_ends_at timestamptz not null,pickup_starts_at timestamptz,pickup_ends_at timestamptz,is_active boolean default true,check(reserved_quantity+sold_quantity<=total_quantity));
create table if not exists public.capacity_slots(id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id),starts_at timestamptz not null,ends_at timestamptz not null,capacity integer not null,booked integer not null default 0,cutoff_minutes integer not null default 30,unique(store_id,starts_at));
alter table public.orders add column if not exists scheduled_for timestamptz; alter table public.orders add column if not exists channel text not null default 'direct';
create table if not exists public.recurring_schedules(id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id),customer_id uuid references public.customer_profiles(id),schedule jsonb not null,items jsonb not null,status text not null default 'active' check(status in('active','paused','cancelled')),next_run_at timestamptz,charge_authorization_reference text,created_at timestamptz default now());
create table if not exists public.group_orders(id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id),host_token uuid not null default gen_random_uuid() unique,join_code text not null unique,deadline timestamptz not null,status text not null default 'open' check(status in('open','locked','confirmed','expired','cancelled')),payment_mode text not null check(payment_mode in('host','individual')),created_at timestamptz default now());
create table if not exists public.group_order_participants(id uuid primary key default gen_random_uuid(),group_order_id uuid not null references public.group_orders(id),participant_token uuid not null default gen_random_uuid() unique,name text not null,items jsonb not null default '[]',allocated_amount numeric(12,2) default 0,paid_amount numeric(12,2) default 0,status text default 'joined',unique(group_order_id,participant_token));
create table if not exists public.reservations(id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id),access_token uuid not null default gen_random_uuid() unique,starts_at timestamptz not null,ends_at timestamptz not null,party_size integer not null,table_id uuid,status text not null default 'pending' check(status in('pending','confirmed','seated','completed','cancelled','no_show')),preorder_id uuid references public.orders(id),created_at timestamptz default now());
create table if not exists public.restaurant_tables(id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id),name text not null,capacity integer not null,qr_secret uuid not null default gen_random_uuid() unique,is_active boolean default true,unique(store_id,name));
create table if not exists public.table_sessions(id uuid primary key default gen_random_uuid(),table_id uuid not null references public.restaurant_tables(id),access_token uuid not null default gen_random_uuid() unique,status text not null default 'open' check(status in('open','payment_pending','closed')),assigned_staff uuid references auth.users(id),opened_at timestamptz default now(),closed_at timestamptz);
create table if not exists public.table_service_requests(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.table_sessions(id),kind text not null check(kind in('waiter','water','bill','other')),status text default 'open',created_at timestamptz default now());
create table if not exists public.bill_allocations(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.table_sessions(id),participant_token uuid not null,order_item_id uuid references public.order_items(id),amount numeric(12,2) not null,discount_share numeric(12,2) default 0,fee_share numeric(12,2) default 0,tip numeric(12,2) default 0,paid_amount numeric(12,2) default 0,payment_reference text,idempotency_key text unique);
create table if not exists public.channel_integrations(id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id),provider text not null,status text default 'disconnected',credentials_reference text,commission_percent numeric(6,3) default 0,last_sync_at timestamptz,last_error text,unique(store_id,provider));
create table if not exists public.external_order_map(id uuid primary key default gen_random_uuid(),integration_id uuid not null references public.channel_integrations(id),external_order_id text not null,order_id uuid references public.orders(id),payload_hash text not null,status text not null,retry_count integer default 0,last_error text,unique(integration_id,external_order_id));
create table if not exists public.preparation_stations(id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id),name text not null,capacity integer not null default 1,is_active boolean default true,unique(store_id,name));
alter table public.products add column if not exists station_id uuid references public.preparation_stations(id); alter table public.products add column if not exists preparation_minutes integer; alter table public.products add column if not exists selling_model jsonb not null default '{"type":"fixed"}';
create table if not exists public.inventory_items(id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id),name text not null,unit text not null,on_hand numeric(14,3) not null default 0,reorder_level numeric(14,3) default 0,unique(store_id,name));
create table if not exists public.recipe_components(product_id uuid not null references public.products(id),inventory_item_id uuid not null references public.inventory_items(id),quantity numeric(14,3) not null check(quantity>0),primary key(product_id,inventory_item_id));
create table if not exists public.menu_import_jobs(id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id),source_files jsonb not null,status text not null default 'uploaded' check(status in('uploaded','reviewing','approved','published','rejected')),progress integer default 0,approved_by uuid references auth.users(id),approved_at timestamptz,created_at timestamptz default now());
create table if not exists public.menu_import_items(id uuid primary key default gen_random_uuid(),job_id uuid not null references public.menu_import_jobs(id),kind text not null check(kind in('category','product','option')),draft_data jsonb not null,confidence numeric(5,4),ambiguities jsonb not null default '[]',status text not null default 'needs_review' check(status in('needs_review','approved','rejected')),created_at timestamptz default now());

do $$ declare t text; begin foreach t in array array['customer_consents','customer_segment_rules','retention_campaigns','message_deliveries','value_wallets','value_ledger','product_costs','order_costs','substitution_proposals','order_issues','resolution_actions','limited_offers','capacity_slots','recurring_schedules','group_orders','group_order_participants','reservations','restaurant_tables','table_sessions','table_service_requests','bill_allocations','channel_integrations','external_order_map','preparation_stations','inventory_items','recipe_components','menu_import_jobs','menu_import_items'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy "staff manage operational records" on public.customer_segment_rules for all using(public.is_org_member(organization_id,array['owner','admin','manager'])) with check(public.is_org_member(organization_id,array['owner','admin','manager']));
create policy "staff manage store limited offers" on public.limited_offers for all using(public.is_store_member(store_id,array['admin','manager'])) with check(public.is_store_member(store_id,array['admin','manager']));
create policy "staff manage capacity" on public.capacity_slots for all using(public.is_store_member(store_id,array['admin','manager'])) with check(public.is_store_member(store_id,array['admin','manager']));
create policy "staff manage tables" on public.restaurant_tables for all using(public.is_store_member(store_id,array['admin','manager'])) with check(public.is_store_member(store_id,array['admin','manager']));
create policy "staff manage stations" on public.preparation_stations for all using(public.is_store_member(store_id,array['admin','manager'])) with check(public.is_store_member(store_id,array['admin','manager']));
create policy "staff manage inventory" on public.inventory_items for all using(public.is_store_member(store_id,array['admin','manager'])) with check(public.is_store_member(store_id,array['admin','manager']));
create policy "staff manage imports" on public.menu_import_jobs for all using(public.is_store_member(store_id,array['admin','manager'])) with check(public.is_store_member(store_id,array['admin','manager']));

create or replace function public.reserve_limited_offer(p_offer_id uuid,p_quantity integer) returns boolean language plpgsql security definer set search_path=public as $$ begin update public.limited_offers set reserved_quantity=reserved_quantity+p_quantity where id=p_offer_id and is_active and now() between sale_starts_at and sale_ends_at and total_quantity-reserved_quantity-sold_quantity>=p_quantity; return found; end $$;
create or replace function public.apply_wallet_entry(p_wallet_id uuid,p_amount numeric,p_type text,p_reason text,p_idempotency text) returns numeric language plpgsql security definer set search_path=public as $$ declare v_balance numeric; begin select balance into v_balance from public.value_wallets where id=p_wallet_id for update; if not found or (p_amount<0 and v_balance+p_amount<0) then raise exception 'Insufficient or missing wallet'; end if; insert into public.value_ledger(wallet_id,amount,entry_type,reason,idempotency_key) values(p_wallet_id,p_amount,p_type,p_reason,p_idempotency) on conflict(idempotency_key) do nothing; update public.value_wallets set balance=balance+p_amount where id=p_wallet_id and found; return (select balance from public.value_wallets where id=p_wallet_id); end $$;
comment on table public.order_costs is 'Estimated contribution inputs. Revenue - refunds - configured product, packaging, payment, delivery, commission and discount costs. Not audited net profit.';
